function prepareLeadPilot({ request }) {
  if (!request || typeof request !== "object" || Array.isArray(request))
    throw new Error("Provide a lead object or an object containing leads.");
  const source = request.leads === undefined ? [request] : request.leads;
  if (!Array.isArray(source) || source.length === 0) throw new Error("Provide at least one lead.");
  const text = (value, name, fallback = "") => {
    if (value === undefined || value === null || value === "") return fallback;
    if (typeof value !== "string") throw new Error(name + " must be text.");
    return value;
  };
  const senderName = text(request.sender_name, "sender_name", "Your Name"),
    senderCompany = text(request.sender_company, "sender_company", "Your Company"),
    senderValue = text(
      request.value_prop,
      "value_prop",
      "We help companies save time with automation.",
    ),
    calendarLink = text(request.calendar_link, "calendar_link");
  const leads = source.map((lead, index) => {
    if (
      !lead ||
      typeof lead !== "object" ||
      Array.isArray(lead) ||
      typeof lead.name !== "string" ||
      !lead.name.trim()
    )
      throw new Error("Lead " + (index + 1) + " requires a name.");
    return {
      name: lead.name,
      email: text(lead.email, "email"),
      title: text(lead.title, "title"),
      company: text(lead.company, "company"),
      industry: text(lead.industry, "industry"),
      companyDescription: text(lead.company_description, "company_description"),
      linkedinUrl: text(lead.linkedin_url, "linkedin_url"),
      notes: text(lead.notes, "notes"),
      senderName,
      senderCompany,
      senderValue,
      calendarLink,
    };
  });
  return { leads };
}

const body = $input.first().json.body ?? $input.first().json;
return prepareLeadPilot({ request: body }).leads.map((lead, index) => ({
  json: lead,
  pairedItem: { item: 0 },
}));

function validateLeadPilotEmail(value) {
  if (typeof value === "string") {
    try {
      value = JSON.parse(value);
    } catch {
      throw new Error("The model response is not JSON.");
    }
  }
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("The model response must be an email object.");
  const required = (v, name) => {
    if (typeof v !== "string" || !v.trim())
      throw new Error("Generated " + name + " is empty or missing.");
    return v;
  };
  return {
    subjectLine: required(value.subjectLine, "subjectLine"),
    emailBody: required(value.emailBody, "emailBody"),
    followUp: {
      subject: required(value.followUp?.subject, "followUp.subject"),
      body: required(value.followUp?.body, "followUp.body"),
    },
  };
}
function leadPilotPrompt(lead) {
  return (
    "Write a cold email:\n\nRecipient: " +
    lead.name +
    "\nTitle: " +
    lead.title +
    "\nCompany: " +
    lead.company +
    "\nIndustry: " +
    lead.industry +
    "\nAbout Company: " +
    lead.companyDescription +
    "\nNotes: " +
    lead.notes +
    "\n\nSender: " +
    lead.senderName +
    " at " +
    lead.senderCompany +
    "\nValue Prop: " +
    lead.senderValue +
    "\nCalendar: " +
    lead.calendarLink
  );
}

return $input.all().map((item, index) => ({
  json: { ...item.json, prompt: leadPilotPrompt(item.json) },
  pairedItem: { item: index },
}));

