  leads = $("Prepare One Lead Prompt").all();
if (items.length !== leads.length) throw new Error("Lead response count differs.");
return items.map((item, index) => {
  const { prompt, ...lead } = leads[index].json;
  return {
    json: { ...lead, ...validateLeadPilotEmail(item.json), generatedAt: new Date().toISOString() },
    pairedItem: { item: index },
  };
});

